// Quick test - just run training
using Microsoft.ML;
using Microsoft.ML.Data;

public class TicketData
{
    [LoadColumn(0)] public string Subject { get; set; } = "";
    [LoadColumn(1)] public string Description { get; set; } = "";
    [LoadColumn(2)] public float Priority { get; set; }
    [LoadColumn(3)] public string Category { get; set; } = "";
}

var mlContext = new MLContext(seed: 42);
Console.WriteLine("Loading data...");
var dataPath = "/tmp/sv-e0e85911f93b4de19668e76c799246b7/TicketClassifier/Data/tickets.csv";
var data = mlContext.Data.LoadFromTextFile<TicketData>(dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
Console.WriteLine("Data loaded");
var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
Console.WriteLine("Data split");
var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", "Subject")
    .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", "Description"))
    .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", "Priority"))
    .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", "Category"))
    .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features", maximumNumberOfIterations: 100))
    .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
Console.WriteLine("Fitting...");
var model = pipeline.Fit(split.TrainSet);
Console.WriteLine("Done!");
EOF
